      '--dsw-alias-bg-layer-1': { light: [255, 255, 255, 0.96], dark: [12, 20, 33, 0.94] },
      '--dsw-alias-bg-layer-2': { light: [236, 241, 251, 0.93], dark: [18, 29, 47, 0.9] },
      '--dsw-alias-bg-overlay': { light: [255, 255, 255, 0.99], dark: [21, 34, 58, 0.97] },
